using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "BoostHeveliusLinkEffectCustomTag", menuName = "Data/Battle/Battle Actions/Tags/BoostHeveliusLinkEffectCustomTag", order = 0)]
public class BoostHeveliusLinkEffectCustomTag : Tag
{
	[SerializeField]
	private PlayerEffectsList playerEffectsList;

	public override string GetTagDescription()
	{
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedAddDie(), 999999999).Replace("999999999", ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedX()) + playerEffectsList.PlayerBoostEffect.GetDieDiscardedDuringDrawPhasePurificationDescription();
	}
}
